#include <algorithm>
#include <iostream>
#include <string>
using namespace std;
void solve(istream& in, ostream& out) {
    string answer[3], guess[3];
    for (int r = 0; r < 3; ++r) in >> answer[r];
    for (int r = 0; r < 3; ++r) in >> guess[r];
    int green = 0, a[26] = {}, g[26] = {};
    for (int r = 0; r < 3; ++r) {
        for (int c = 0; c < 3; ++c) {
            if (answer[r][c] == guess[r][c]) ++green;
            else {
                ++a[answer[r][c] - 'A'];
                ++g[guess[r][c] - 'A'];
            }
        }
    }
    int yellow = 0;
    for (int b = 0; b < 26; ++b) yellow += min(a[b], g[b]);
    out << green << '\n' << yellow << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
