#include <array>
#include <iostream>
using namespace std;
int comparison(const array<int, 4>& x, const array<int, 4>& y) {
    int balance = 0;
    for (int a : x)
        for (int b : y) balance += (a > b) - (a < b);
    return balance;
}
bool possible(const array<int, 4>& a, const array<int, 4>& b) {
    int orientation = comparison(a, b);
    if (orientation == 0) return false;
    for (int w = 1; w <= 10; ++w)
        for (int x = w; x <= 10; ++x)
            for (int y = x; y <= 10; ++y)
                for (int z = y; z <= 10; ++z) {
                    array<int, 4> c = {{w, x, y, z}};
                    if (comparison(b, c) * orientation > 0 &&
                        comparison(c, a) * orientation > 0) return true;
                }
    return false;
}
void solve(istream& in, ostream& out) {
    int tests;
    in >> tests;
    while (tests--) {
        array<int, 4> a, b;
        for (int& v : a) in >> v;
        for (int& v : b) in >> v;
        out << (possible(a, b) ? "yes" : "no") << '\n';
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
