#include <algorithm>
#include <iostream>
#include <limits>
using namespace std;
void solve(istream& in, ostream& out) {
    int tests;
    in >> tests;
    while (tests--) {
        int n;
        in >> n;
        long long alternating = 0, total = 0;
        long long oddMinimum = numeric_limits<long long>::max();
        bool valid = true;
        for (int i = 1; i <= n; ++i) {
            long long hunger;
            in >> hunger;
            total += hunger;
            alternating = hunger - alternating;
            if (i % 2 == 1) oddMinimum = min(oddMinimum, alternating);
            else if (alternating < 0) valid = false;
        }
        long long target;
        if (n % 2 == 1) {
            target = alternating;
            if (target < 0 || oddMinimum < target) valid = false;
        } else {
            target = oddMinimum;
            if (alternating != 0 || target < 0) valid = false;
        }
        out << (valid ? total - 1LL * n * target : -1LL) << '\n';
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
